const qnet=code=>`https://www.q-net.or.kr/crf005.do?id=crf00503&gSite=Q&jmCd=${code}`;
const table=(title,rows)=>`<div class="verified-table" tabindex="0" role="region" aria-label="${title}"><table><thead><tr><th>비교 항목</th><th>상담할 질문</th></tr></thead><tbody>${rows.map(([a,b])=>`<tr><td>${a}</td><td>${b}</td></tr>`).join('')}</tbody></table></div>`;
const section=(heading,...parts)=>`<h2>${heading}</h2>${parts.map(p=>p.startsWith('<')?p:`<p>${p}</p>`).join('')}`;
const faqs=require('./cert4-faq-20261008.cjs');

module.exports=function make(d){
 const [name,slug,title,key,code,mode,time,fee,subjects,angle,study,practice,course,career,risk,related]=d;
 const written=mode==='필기·실기';
 const official=written
  ?`Q-Net의 ${name} 안내에서 필기는 객관식 60문항·60분, 실기는 ${time} 작업형으로 확인됩니다. 필기와 실기 합격 기준은 각각 100점 만점에 60점 이상입니다. 필기 범위는 ${subjects}입니다. 여기 적은 시험 방식은 2026년 10월 8일 확인한 내용으로, 실제 접수 회차의 공지와 적용 출제기준을 다시 확인해야 합니다.`
  :`Q-Net의 ${name} 안내에는 필기시험 없이 ${time} 작업형 실기가 제시됩니다. 합격 기준은 100점 만점에 60점 이상입니다. 필기 교재나 필기 대비 패키지를 먼저 살 필요가 없는 종목이라는 뜻이지, 이론과 도면 이해 없이 작업만 반복하면 된다는 뜻은 아닙니다. 실제 접수 회차의 공개문제와 지참준비물 공지를 확인하세요.`;
 const body=[
  section('이 종목을 고르기 전에 확인할 일',
   `${angle} 자격 이름이 비슷한 과정이 있어도 시험 과제와 이후 맡을 업무는 같지 않을 수 있습니다. 자신이 배우려는 기술을 한 문장으로 적고 공식 종목명, 교육기관의 과정명, 희망 채용공고의 업무를 나란히 놓으세요. 이 세 항목이 서로 맞지 않으면 단순히 인기가 높다는 이유로 수강을 결정하지 않는 편이 좋습니다.`,
   official),
  section(written?'필기 공부의 우선순위':'도면과 작업 조건을 읽는 법',
   `${study} 먼저 현재 적용되는 Q-Net 출제기준의 항목을 체크리스트로 옮기고, 자신이 설명할 수 있는 부분과 용어만 외운 부분을 다르게 표시하세요. 오래된 후기의 출제 순서나 개인 경험을 현재 시험 규칙으로 받아들이지 않는 것이 중요합니다.`,
   written?`객관식 기출을 풀 때에는 정답 번호보다 왜 다른 선택지가 맞지 않는지 한 줄로 설명해 보세요. 틀린 문제는 범위의 어느 단원에 속하는지 기록하고, 이해하지 못한 개념은 공식 기준과 교재의 해당 부분으로 돌아가 확인합니다. 실기 연습을 시작할 시기를 필기 합격 뒤로 무조건 미루지 말고 교육 일정과 장비 접근성을 미리 살펴보세요.`:`필기가 없더라도 작업 순서와 재료·공구의 역할, 도면에서 요구하는 결과를 설명할 수 있어야 합니다. 그림만 보고 동작을 흉내 내는 연습과 조건을 이해한 뒤 작업하는 연습은 다릅니다. 실습 전에는 공개문제에서 무엇을 만들고 어떤 조건을 지켜야 하는지 지도자에게 말로 설명해 보세요.`),
  section('실기 연습은 결과와 과정을 같이 봅니다',
   `${practice} 편집자의 학습 제안은 한 번의 연습마다 시작 조건, 본인이 직접 수행한 단계, 지도자가 개입한 단계, 완성 뒤 확인한 문제를 별도로 기록하는 것입니다. 좋은 결과 사진 한 장만으로 실제 독립 수행 능력을 판단하지 마세요.`,
   `공개문제와 시험장 안내를 확인한 다음 연습의 범위를 정하세요. 현장이나 작업실의 안전 지시가 이 글의 일반적인 설명보다 우선합니다. 허용되지 않은 도구를 가져오거나 위험한 장비를 동영상만 보고 혼자 다루는 방식은 피해야 합니다. 작업 속도만 빠르게 만드는 것보다 정리·안전·결과 점검을 포함한 한 차례의 흐름을 반복하는 것이 유용합니다.`),
  section('교육과정은 개인 연습 기회로 비교합니다',
   table(`${name} 과정 비교`,[['시험 범위','올해 적용 출제기준과 공개문제를 다루나요'],['개인 연습','전체 과정을 본인이 수행하는 횟수는 몇 번인가요'],['피드백','어느 단계에서 오류를 설명받고 다시 해보나요'],['장비·재료','제공, 대여, 개인 구입 품목은 무엇인가요'],['보강·안전','결석 보강과 장비 안전교육은 어떻게 진행되나요']]),
   `${course} 상담에서 시연 시간과 본인의 손으로 연습하는 시간을 따로 묻는 것이 좋습니다. 수업 시간이 길어도 관찰만 하는 비율이 높으면 준비의 성격이 달라집니다. 시험장과 같은 작업을 보장한다는 광고 문구보다 현재 공개문제의 어느 부분을 어떻게 연습하는지 설명을 요청하세요.`),
  section('수험료와 실제 준비비를 분리합니다',
   `Q-Net에 표시된 ${name} 수험료는 ${written?`필기 14,500원, 실기 ${fee}`:`실기 ${fee}`}입니다. 이는 시험 접수비이며 학원 수강료, 장비·재료, 추가 연습, 교통비를 모두 포함한 금액이 아닙니다. 접수 직전 금액 변경 여부는 Q-Net에서 다시 확인하세요.`,
   `예산표에는 기본 수강료, 포함된 실습 횟수, 추가 연습료, 개인 도구 구입·대여, 이동 시간을 각각 적어 보세요. 처음 보이는 패키지 가격이 낮더라도 한 번 더 연습할 때 드는 비용이 크면 총비용은 달라집니다. 반대로 모든 장비를 미리 사는 것이 합리적인 것도 아닙니다. 현재 시험 지참 목록과 교육기관 제공 품목을 대조한 뒤 필요한 것만 준비하세요.`),
  section('취득 이후의 일을 미리 확인합니다',
   `${career} 실제 구인공고에서는 자격증 우대 여부와 경력, 근무시간, 작업 장소, 추가 업무를 각각 확인해야 합니다. 자격증 한 장만으로 채용이나 일정 수입이 보장되지 않습니다. 시험 연습을 실제 고객 의뢰나 현장 업무 경력으로 적지 말고, 본인이 직접 수행한 교육용 작업이라고 정확히 표시하세요.`,
   `가상의 비교 사례로 동일한 자격을 우대하는 공고 두 개가 있어도 한 곳은 제작·작업 중심이고 다른 곳은 고객 응대와 일정 관리까지 포함할 수 있습니다. 희망 업무가 어느 쪽인지 확인하고 부족한 경험을 채울 교육을 선택하세요. 취득 목표가 창업이라면 시험 준비와 별도로 작업 공간, 운영 비용, 고객 관리의 현실성을 검토해야 합니다.`),
  section('접수 직전 마지막 점검',
   `${risk} 시험장·회차별 장비와 준비물, 공개문제 개정, 출제기준 적용기간을 공식 페이지에서 확인하세요. 캡처한 오래된 목록 대신 접수한 회차의 안내를 사용합니다. 이 글의 이미지 역시 학습 주제를 설명하기 위한 AI 제작물이지 공식 시험 과제나 지참준비물 사진이 아닙니다.`,
   `일정을 정할 때는 시험일만이 아니라 실습장 예약, 이동과 휴식, 결과 확인 이후의 다음 단계까지 생각하세요. 특히 서서 하는 작업이나 반복 동작이 있다면 본인에게 가능한 연습 강도를 교육 담당자와 상의합니다. 실제 작업은 안전교육과 지도 아래 진행하고, 불확실한 응시 조건이나 과제는 Q-Net 안내에 문의하는 것이 가장 정확합니다.`)
 ].join('\n');
 return {slug,title,category:'license',label:'자격증 취득',image:`/assets/cert4-${key}-20261008.webp`,imageAlt:`${name} 준비 주제를 설명하는 AI 제작 이미지`,check:written?'필기 범위·실기 연습·총비용':'공개문제·안전교육·총비용',description:`${name}의 ${mode} 시험 방식과 ${time} 작업형, 교육과정과 총비용을 공식 자료에 근거해 비교합니다.`,intro:`${name}를 준비한다면 시험 방식만 보고 과정부터 결제하지 마세요. ${angle}`,body,faq:faqs[code],sources:[[name+' 시험 안내·출제기준',qnet(code)],['Q-Net 수험자 지참준비물','https://www.q-net.or.kr/rcv013.do?id=rcv01312']],related,verifiedAt:'2026-10-08',publishedAt:'2026-10-08'};
};
